void	dei_out_pulse_after_ign_off( void *payload )
{    	
	if( !get_ss_lock() && !get_rs_gwr() )
	{
		DEI_OUT_PULSE_AFTER_IGN_OFF( 1 , 100*60 , 1 , 1 ) ; 
	}	
}

//--------------------------------------------------------------------------//

void dei_out_pulse_after_ign_off_reset( void*payload )
{
	DEI_OUT_PULSE_AFTER_IGN_OFF_RESET();
}
